from pathlib import Path
import shutil, sys, json
sys.stdout.reconfigure(encoding='utf-8')
base=Path(__file__).resolve().parent
snapshot=base/'revisions'/'v0.1-before-style-01'
snapshot.mkdir(parents=True,exist_ok=True)
names=['editorial-agent-architecture.md','role-contracts.md','chapter-packet-and-pilot.md','editorial-agent-architecture.docx','editorial-agent-architecture.pdf']
for name in names:
    target=snapshot/name
    if not target.exists():shutil.copy2(base/name,target)
def replace_once(text,old,new):
    if text.count(old)!=1:raise ValueError('Expected one anchor: '+old[:90])
    return text.replace(old,new,1)
style=(base/'editorial-style.md').read_text(encoding='utf-8-sig')
rule=style.split('## 1. Правило для всей редакции\n\n',1)[1].split('\n\n',1)[0]
p=base/'editorial-agent-architecture.md'
s=p.read_text(encoding='utf-8-sig')
s=replace_once(s,'Версия 0.1 ·','Версия 0.2 ·')
s=replace_once(s,'### Две карты одной книги','**Жанр задан автором:** лёгкая футурологическая проза с научной глубиной. Обязательное правило STYLE-01 изложено в `editorial-style.md` и применяется с первого черновика. Общие приёмы публичной подачи Евгения Кузнецова используются как ориентир для самостоятельного голоса книги.\n\n### Две карты одной книги')
s=replace_once(s,'## 6. Как добиться чтения, похожего на путешествие\n\n','## 6. Как добиться чтения, похожего на путешествие\n\n### Обязательное правило STYLE-01\n\n'+rule+'\n\nПолный стандарт, наблюдения по публичным текстам и критерии приёмки сохранены в `editorial-style.md`. Научные методы, библиография и дополнительные расчёты могут размещаться в примечаниях; существенные ограничения и само объяснение механизма остаются в основном тексте. Автор получает это требование до написания главы.\n\n### Читательский маршрут\n\n')
s=replace_once(s,'- Глава добавляет новый шаг в книгу; повторения оправданы этим шагом.','- Глава добавляет новый шаг в книгу; повторения оправданы этим шагом.\n- Приёмка по STYLE-01 отдельно проверяет понимание, интерес и научную точность. Если текст систематически теряет читателя, он возвращается на композиционную или литературную правку. Агентная симуляция и реальные читательские отзывы учитываются раздельно.')
p.write_text(s,encoding='utf-8')
p=base/'role-contracts.md';s=p.read_text(encoding='utf-8-sig')
s=replace_once(s,'Проект 0.1 ·','Проект 0.2 ·')
s=replace_once(s,'## Общий контракт для любого исполнителя\n\n','## Общий контракт для любого исполнителя\n\nОбязательно применяй STYLE-01 из `editorial-style.md`: лёгкая футурологическая проза, научно проверяемые основания, самостоятельный голос авторов. Научный аппарат поддерживает чтение; существенные ограничения и объяснение механизма остаются в основном тексте. Направление стиля задано автором и действует с первого черновика.\n\n')
s=replace_once(s,'## 7. Архитектор читательского пути\n\n','## 7. Архитектор читательского пути\n\nПо STYLE-01 планируй предметные ситуации, смену масштаба и чередование умственной нагрузки. Научная глубина должна проявляться через объяснение механизма; порядок открытия идей должен поддерживать интерес. Не делай одинаковую композицию обязательной для всех глав.\n\n')
s=replace_once(s,'## 9. Автор главы\n\n','## 9. Автор главы\n\nС первого черновика пиши по STYLE-01: ясный разговор с образованным читателем, конкретные ситуации, неожиданные связи, механизм и последствия выбора. Не откладывай жанр на финальную редактуру. Необходимую фактуру и ограничения оставляй рядом с выводом; подробную методику и справочный аппарат размещай в предусмотренном втором уровне чтения.\n\n')
s=replace_once(s,'## 11. Редактор авторского голоса\n\n','## 11. Редактор авторского голоса\n\nПрименяй STYLE-01 и самостоятельный голос книги. Общие приёмы футурологической прозы включают понятные аналогии, смену масштаба и предметное будущее; индивидуальную манеру названного автора не воспроизводи. Проверяй, что лёгкость получена ясностью объяснения, а научный вывод сохранил существенные ограничения.\n\n')
s=replace_once(s,'## 14. Холодный читатель\n\n','## 14. Холодный читатель\n\nПо STYLE-01 отдельно оцени понимание и интерес: перескажи механизм, назови существенное ограничение и запомнившийся пример; укажи точное место, где ослабло желание читать дальше. Сложность мысли сама по себе не считается дефектом; важно, получил ли читатель достаточно опор для её понимания.\n\n')
s=replace_once(s,'## 15. Корректор\n\n','## 15. Корректор\n\nСохраняй лёгкую интонацию, предусмотренную STYLE-01. Нормативное исправление языка не должно превращать живой авторский текст в формальное научное изложение.\n\n')
p.write_text(s,encoding='utf-8')
p=base/'chapter-packet-and-pilot.md';s=p.read_text(encoding='utf-8-sig')
s=replace_once(s,'Версия 0.1 ·','Версия 0.2 ·')
s=replace_once(s,'| Голос и объём | Принятый образец, ориентир объёма, плотность научного аппарата |','| Голос и объём | Обязательное STYLE-01, принятый авторский образец и ориентир объёма |\n| Два уровня чтения | Что остаётся в основном тексте; что уходит в примечания без изменения силы вывода |\n| Проверка чтения | Может ли читатель объяснить механизм и ограничение, вспомнить пример и назвать место потери интереса |')
s=replace_once(s,'### Приёмка пилота\n\n','### Приёмка пилота\n\nПрименяется STYLE-01 из `editorial-style.md`. Пилот читается как лёгкий футурологический фрагмент с научной глубиной. Отдельно оцениваются интерес и понимание: читатель пересказывает механизм, называет существенное ограничение и запомнившуюся ситуацию. Текст без примечаний сохраняет достаточное объяснение и честный масштаб вывода.\n\n')
p.write_text(s,encoding='utf-8')
builder=(base/'build_design_docx.py').read_text(encoding='utf-8-sig')
builder=builder.replace('editorial-agent-architecture.md','editorial-style.md').replace('editorial-agent-architecture.docx','editorial-style.docx')
builder=builder.replace('Право на решение: проект агентной редакции','Право на решение: правило стиля STYLE-01')
builder=builder.replace('Проект агентной редакции','Правило стиля STYLE-01').replace('Роли, общая память, управление, проверки и пилот','Лёгкая футурологическая проза с научной глубиной')
(base/'build_style_docx.py').write_text(builder,encoding='utf-8')
print(json.dumps({'updated':['editorial-agent-architecture.md','role-contracts.md','chapter-packet-and-pilot.md'],'new_rule':'editorial-style.md','previous_versions':str(snapshot)},ensure_ascii=False))
